{-| @Backend.Runtime.Kernel.Column — sums, extremes, filters, projection, bitmaps, search and
    gather over packed 64-bit rows, as `Pudu.Runtime.Column` answers them. -}
module Pudu.Backend.Runtime.Kernel.Column (columnKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
columnKernelParts :: [(Text, [Text], [Text])]
columnKernelParts =
  [ ("column_valid", ["kernel_read"],
      [ "/* Whether a row's bit is set in a bitmap; a word outside it reads as unset. */"
      , "static int pudu_column_valid(pudu_text bitmap, int64_t row) {"
      , "  uint64_t word;"
      , "  if (row < 0 || !pudu_kernel_read(bitmap, (row >> 6) * 8, &word)) return 0;"
      , "  return (int)((word >> (row & 63)) & 1);"
      , "}"
      ])
  , ("column_at", ["kernel_read", "kernel_signed"],
      [ "/* A row's word, when it lies inside the data. */"
      , "static int pudu_column_at(pudu_text data, int64_t row, uint64_t *word) {"
      , "  return pudu_kernel_read(data, pudu_kernel_signed((uint64_t)row * 8), word);"
      , "}"
      ])
  , ("column_words", ["kernel_fresh"],
      [ "/* A zeroed bitmap of one bit per row, in whole words. */"
      , "static pudu_text pudu_column_words(int64_t rows, unsigned char **bytes) {"
      , "  return pudu_kernel_fresh((size_t)((rows + 63) >> 6) * 8, bytes);"
      , "}"
      ])
  , ("column_triple", ["bytes_wrap", "make"],
      [ "static pudu_box *pudu_column_triple(pudu_text data, pudu_text validity, int64_t rows) {"
      , "  pudu_box *tuple = pudu_box_new(3);"
      , "  tuple->fields[0].box = pudu_bytes_wrap(data);"
      , "  tuple->fields[1].box = pudu_bytes_wrap(validity);"
      , "  tuple->fields[2].integer = pudu_make((uint64_t)rows, 0);"
      , "  return tuple;"
      , "}"
      ])
  , ("column_sum_u64", ["column_valid", "column_at", "kernel_signed", "make"],
      [ "static pudu_int pudu_column_sum_u64(pudu_box *data, pudu_box *validity, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  uint64_t total = 0, word;"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (pudu_column_valid(validity->fields[0].text, row) && pudu_column_at(data->fields[0].text, row, &word)) total += word;"
      , "  return pudu_make(total, 0);"
      , "}"
      ])
  , ("column_any", ["column_valid", "column_at", "kernel_signed"],
      [ "/* Whether an extreme exists: some row is valid and readable. */"
      , "static int pudu_column_any(pudu_box *data, pudu_box *validity, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  uint64_t word;"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (pudu_column_valid(validity->fields[0].text, row) && pudu_column_at(data->fields[0].text, row, &word)) return 1;"
      , "  return 0;"
      , "}"
      ])
  , ("column_extreme_u64", ["column_valid", "column_at", "kernel_signed", "make"],
      [ "static pudu_int pudu_column_extreme_u64(pudu_box *data, pudu_box *validity, pudu_int rows, int greatest) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  uint64_t best = 0, word;"
      , "  int found = 0;"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (pudu_column_valid(validity->fields[0].text, row) && pudu_column_at(data->fields[0].text, row, &word)) {"
      , "      if (!found || (greatest ? word > best : word < best)) best = word;"
      , "      found = 1;"
      , "    }"
      , "  return pudu_make(best, 0);"
      , "}"
      ])
  , ("column_extreme_f64", ["column_valid", "column_at", "kernel_signed", "float_decode"],
      [ "/* Selection by <=, so NaN and signed zeros answer as the reference does. */"
      , "static uint64_t pudu_column_extreme_f64(pudu_box *data, pudu_box *validity, pudu_int rows, int greatest) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  uint64_t best = 0, word;"
      , "  int found = 0;"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (pudu_column_valid(validity->fields[0].text, row) && pudu_column_at(data->fields[0].text, row, &word)) {"
      , "      if (!found) best = word;"
      , "      else if (pudu_float_decode(best) <= pudu_float_decode(word)) best = greatest ? word : best;"
      , "      else best = greatest ? best : word;"
      , "      found = 1;"
      , "    }"
      , "  return best;"
      , "}"
      ])
  , ("column_filter", ["column_at", "column_words", "kernel_read", "kernel_put", "kernel_signed", "float_decode", "bytes_wrap", "text_literal"],
      [ "/* A selection bitmap of the valid rows past the threshold: unsigned above"
      , "   (0), float above (1) or float below (2). */"
      , "static pudu_box *pudu_column_filter(pudu_box *data, pudu_box *validity, pudu_int rows, uint64_t threshold, int mode) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  unsigned char *bytes;"
      , "  pudu_text chosen;"
      , "  if (count <= 0) return pudu_bytes_wrap(pudu_text_literal(\"\", 0));"
      , "  chosen = pudu_column_words(count, &bytes);"
      , "  for (int64_t index = 0; index < (count + 63) >> 6; ++index) {"
      , "    uint64_t valid = 0, picked = 0, word;"
      , "    (void)pudu_kernel_read(validity->fields[0].text, index * 8, &valid);"
      , "    for (int bit = 0; bit < 64; ++bit) {"
      , "      int64_t row = index * 64 + bit;"
      , "      if (row >= count || ((valid >> bit) & 1) == 0 || !pudu_column_at(data->fields[0].text, row, &word)) continue;"
      , "      if (mode == 0 ? word > threshold"
      , "          : mode == 1 ? pudu_float_decode(word) > pudu_float_decode(threshold)"
      , "          : pudu_float_decode(word) < pudu_float_decode(threshold)) picked |= UINT64_C(1) << bit;"
      , "    }"
      , "    pudu_kernel_put(bytes + index * 8, picked, 8);"
      , "  }"
      , "  return pudu_bytes_wrap(chosen);"
      , "}"
      ])
  , ("column_project", ["column_valid", "column_at", "column_words", "column_triple", "kernel_fresh", "kernel_put", "kernel_signed", "text_literal"],
      [ "/* The selected rows, packed, with their validity and their count. */"
      , "static pudu_box *pudu_column_project(pudu_box *data, pudu_box *validity, pudu_box *selection, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits), matches = 0, target = 0;"
      , "  unsigned char *values, *bits;"
      , "  pudu_text packed, kept;"
      , "  if (count <= 0) return pudu_column_triple(pudu_text_literal(\"\", 0), pudu_text_literal(\"\", 0), 0);"
      , "  for (int64_t row = 0; row < count; ++row) matches += pudu_column_valid(selection->fields[0].text, row);"
      , "  packed = pudu_kernel_fresh((size_t)matches * 8, &values);"
      , "  kept = pudu_column_words(matches, &bits);"
      , "  for (int64_t row = 0; row < count; ++row) {"
      , "    uint64_t word = 0;"
      , "    if (!pudu_column_valid(selection->fields[0].text, row)) continue;"
      , "    (void)pudu_column_at(data->fields[0].text, row, &word);"
      , "    pudu_kernel_put(values + target * 8, word, 8);"
      , "    if (pudu_column_valid(validity->fields[0].text, row)) bits[target >> 3] |= (unsigned char)(1u << (target & 7));"
      , "    target += 1;"
      , "  }"
      , "  return pudu_column_triple(packed, kept, matches);"
      , "}"
      ])
  , ("column_sum_f64", ["column_valid", "column_at", "kernel_signed", "float_decode", "float_encode"],
      [ "static uint64_t pudu_column_sum_f64(pudu_box *data, pudu_box *validity, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  volatile double total = 0.0;"
      , "  uint64_t word;"
      , "  for (int64_t row = 0; row < count; ++row)"
      , "    if (pudu_column_valid(validity->fields[0].text, row) && pudu_column_at(data->fields[0].text, row, &word))"
      , "      total = total + pudu_float_decode(word);"
      , "  return pudu_float_encode(total);"
      , "}"
      ])
  , ("column_add_f64", ["column_valid", "column_at", "column_words", "kernel_fresh", "kernel_put", "kernel_signed", "float_decode", "float_encode", "bytes_wrap", "text_literal"],
      [ "/* Row sums where both rows are valid; zero and invalid elsewhere. */"
      , "static pudu_box *pudu_column_add_f64(pudu_box *left, pudu_box *left_validity, pudu_box *right, pudu_box *right_validity, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  unsigned char *values = NULL, *bits = NULL;"
      , "  pudu_text sums = pudu_text_literal(\"\", 0), kept = pudu_text_literal(\"\", 0);"
      , "  pudu_box *pair = pudu_box_new(2);"
      , "  if (count > 0) {"
      , "    sums = pudu_kernel_fresh((size_t)count * 8, &values);"
      , "    kept = pudu_column_words(count, &bits);"
      , "  }"
      , "  for (int64_t row = 0; row < count; ++row) {"
      , "    uint64_t a = 0, b = 0;"
      , "    volatile double sum;"
      , "    if (!pudu_column_valid(left_validity->fields[0].text, row) || !pudu_column_valid(right_validity->fields[0].text, row)) continue;"
      , "    (void)pudu_column_at(left->fields[0].text, row, &a);"
      , "    (void)pudu_column_at(right->fields[0].text, row, &b);"
      , "    sum = pudu_float_decode(a) + pudu_float_decode(b);"
      , "    pudu_kernel_put(values + row * 8, pudu_float_encode(sum), 8);"
      , "    bits[row >> 3] |= (unsigned char)(1u << (row & 7));"
      , "  }"
      , "  pair->fields[0].box = pudu_bytes_wrap(sums);"
      , "  pair->fields[1].box = pudu_bytes_wrap(kept);"
      , "  return pair;"
      , "}"
      ])
  , ("column_bitmap", ["column_words", "kernel_read", "kernel_put", "kernel_signed", "bytes_wrap", "text_literal"],
      [ "/* Word by word: and (0), or (1), or the complement of the first cut to the row count (2). */"
      , "static pudu_box *pudu_column_bitmap(pudu_box *left, pudu_box *right, pudu_int rows, int mode) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits), words = (count + 63) >> 6;"
      , "  unsigned char *bytes;"
      , "  pudu_text built;"
      , "  if (count <= 0) return pudu_bytes_wrap(pudu_text_literal(\"\", 0));"
      , "  built = pudu_column_words(count, &bytes);"
      , "  for (int64_t index = 0; index < words; ++index) {"
      , "    uint64_t a = 0, b = 0, word;"
      , "    (void)pudu_kernel_read(left->fields[0].text, index * 8, &a);"
      , "    (void)pudu_kernel_read(right->fields[0].text, index * 8, &b);"
      , "    word = mode == 0 ? (a & b) : mode == 1 ? (a | b) : ~a;"
      , "    if (mode == 2 && index == words - 1 && (count & 63) != 0) word &= (UINT64_C(1) << (count & 63)) - 1;"
      , "    pudu_kernel_put(bytes + index * 8, word, 8);"
      , "  }"
      , "  return pudu_bytes_wrap(built);"
      , "}"
      ])
  , ("column_bitmap_not", ["column_bitmap"],
      [ "static pudu_box *pudu_column_bitmap_not(pudu_box *bitmap, pudu_int rows) {"
      , "  return pudu_column_bitmap(bitmap, bitmap, rows, 2);"
      , "}"
      ])
  , ("column_bitmap_count", ["kernel_read", "kernel_signed", "kernel_int"],
      [ "static pudu_int pudu_column_bitmap_count(pudu_box *bitmap, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits), words = (count + 63) >> 6, total = 0;"
      , "  for (int64_t index = 0; count > 0 && index < words; ++index) {"
      , "    uint64_t word = 0;"
      , "    (void)pudu_kernel_read(bitmap->fields[0].text, index * 8, &word);"
      , "    if (index == words - 1 && (count & 63) != 0) word &= (UINT64_C(1) << (count & 63)) - 1;"
      , "    for (; word != 0; word &= word - 1) total += 1;"
      , "  }"
      , "  return pudu_kernel_int(total);"
      , "}"
      ])
  , ("column_search", ["column_at", "kernel_read", "kernel_signed", "float_decode"],
      [ "/* Binary search over a sorted permutation; a read outside either buffer ends it. */"
      , "static int pudu_column_search(pudu_text data, pudu_text permutation, int64_t count, uint64_t target, int floats, uint64_t *row) {"
      , "  int64_t low = 0, high = count - 1;"
      , "  while (low <= high) {"
      , "    int64_t middle = (low + high) >> 1;"
      , "    uint64_t at, word;"
      , "    int order;"
      , "    if (!pudu_kernel_read(permutation, middle * 8, &at) || !pudu_column_at(data, pudu_kernel_signed(at), &word)) return 0;"
      , "    if (floats) {"
      , "      double held = pudu_float_decode(word), wanted = pudu_float_decode(target);"
      , "      order = held < wanted ? -1 : held == wanted ? 0 : 1;"
      , "    } else order = word < target ? -1 : word == target ? 0 : 1;"
      , "    if (order == 0) { *row = at; return 1; }"
      , "    if (order < 0) low = middle + 1; else high = middle - 1;"
      , "  }"
      , "  return 0;"
      , "}"
      ])
  , ("column_found", ["column_search", "kernel_signed"],
      [ "static int pudu_column_found(pudu_box *data, pudu_box *permutation, pudu_int count, uint64_t target, int floats) {"
      , "  uint64_t row;"
      , "  return pudu_column_search(data->fields[0].text, permutation->fields[0].text, pudu_kernel_signed(count.bits), target, floats, &row);"
      , "}"
      ])
  , ("column_row", ["column_search", "kernel_signed", "kernel_int"],
      [ "/* The row a successful search answers. */"
      , "static pudu_int pudu_column_row(pudu_box *data, pudu_box *permutation, pudu_int count, uint64_t target, int floats) {"
      , "  uint64_t row = 0;"
      , "  (void)pudu_column_search(data->fields[0].text, permutation->fields[0].text, pudu_kernel_signed(count.bits), target, floats, &row);"
      , "  return pudu_kernel_int(pudu_kernel_signed(row));"
      , "}"
      ])
  , ("column_gather", ["column_valid", "column_at", "column_words", "column_triple", "kernel_fresh", "kernel_read", "kernel_put", "kernel_signed", "text_literal"],
      [ "/* Rows in permutation order; an invalid source row gathers as zero and invalid. */"
      , "static pudu_box *pudu_column_gather(pudu_box *data, pudu_box *validity, pudu_box *permutation, pudu_int rows) {"
      , "  int64_t count = pudu_kernel_signed(rows.bits);"
      , "  unsigned char *values, *bits;"
      , "  pudu_text packed, kept;"
      , "  if (count <= 0) return pudu_column_triple(pudu_text_literal(\"\", 0), pudu_text_literal(\"\", 0), 0);"
      , "  packed = pudu_kernel_fresh((size_t)count * 8, &values);"
      , "  kept = pudu_column_words(count, &bits);"
      , "  for (int64_t target = 0; target < count; ++target) {"
      , "    uint64_t source, word = 0;"
      , "    if (!pudu_kernel_read(permutation->fields[0].text, target * 8, &source)) continue;"
      , "    if (!pudu_column_valid(validity->fields[0].text, pudu_kernel_signed(source))) continue;"
      , "    (void)pudu_column_at(data->fields[0].text, pudu_kernel_signed(source), &word);"
      , "    pudu_kernel_put(values + target * 8, word, 8);"
      , "    bits[target >> 3] |= (unsigned char)(1u << (target & 7));"
      , "  }"
      , "  return pudu_column_triple(packed, kept, count);"
      , "}"
      ])
  ]
